import{_ as a,c as t,o as i,ah as o}from"./chunks/framework.C03ZlYVw.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function r(s,e,l,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><h3 id="_1-is-it-possible-to-download-the-challenge-dataset-without-participating-in-the-challenge" tabindex="-1">1. Is it possible to download the challenge dataset without participating in the challenge? <a class="header-anchor" href="#_1-is-it-possible-to-download-the-challenge-dataset-without-participating-in-the-challenge" aria-label="Permalink to “1. Is it possible to download the challenge dataset without participating in the challenge?”">​</a></h3><p>Yes, under controlled access.</p><p>Researchers who do not intend to participate in the challenge but wish to use the dataset must submit a research proposal to the organizing committee at <a href="mailto:mrixfields@outlook.com" target="_blank" rel="noreferrer">mrixfields@outlook.com</a> for review. Access to the dataset will be granted only after approval by the data governance committee.</p><p>All approved users are required to comply with the data usage agreement. In particular:</p><ul><li>Results derived from the dataset may only be published no earlier than <strong>three months after the official end of the challenge</strong></li><li>The <strong>challenge paper</strong> must be properly cited</li><li>The <strong>dataset source</strong> must be explicitly acknowledged in any publication</li></ul><h3 id="_2-can-other-datasets-or-pre-trained-models-be-used-to-develop-the-reconstruction-algorithms" tabindex="-1">2. Can other datasets or pre-trained models be used to develop the reconstruction algorithms? <a class="header-anchor" href="#_2-can-other-datasets-or-pre-trained-models-be-used-to-develop-the-reconstruction-algorithms" aria-label="Permalink to “2. Can other datasets or pre-trained models be used to develop the reconstruction algorithms?”">​</a></h3><p>Yes. Any publicly available datasets may be used for training. However, participants are not allowed to use their own private data in order to ensure the fairness of this challenge. Data augmentation based on the training dataset is allowed.</p><h3 id="_3-what-is-the-maximum-number-of-team-members-allowed" tabindex="-1">3. What is the maximum number of team members allowed? <a class="header-anchor" href="#_3-what-is-the-maximum-number-of-team-members-allowed" aria-label="Permalink to “3. What is the maximum number of team members allowed?”">​</a></h3><p>Each team can consist of up to <strong>6 people</strong>.</p><h3 id="_4-can-we-preprocess-the-data" tabindex="-1">4. Can we preprocess the data? <a class="header-anchor" href="#_4-can-we-preprocess-the-data" aria-label="Permalink to “4. Can we preprocess the data?”">​</a></h3><p>We do not restrict data preprocessing, and we only evaluate the final generation performance. However, the total running time for all data in each task cannot exceed <strong>1 hour</strong>.</p><h3 id="_5-do-we-need-to-upload-the-training-code" tabindex="-1">5. Do we need to upload the training code? <a class="header-anchor" href="#_5-do-we-need-to-upload-the-training-code" aria-label="Permalink to “5. Do we need to upload the training code?”">​</a></h3><p>We do not require teams to upload the training code. Only the <strong>Docker image for the inference code</strong> is required for participation.</p><h3 id="_6-does-the-validation-submission-affect-the-final-ranking" tabindex="-1">6. Does the validation submission affect the final ranking? <a class="header-anchor" href="#_6-does-the-validation-submission-affect-the-final-ranking" aria-label="Permalink to “6. Does the validation submission affect the final ranking?”">​</a></h3><p>No, the validation submission does <strong>not</strong> affect the final ranking.</p><h3 id="_7-how-many-submissions-are-allowed" tabindex="-1">7. How many submissions are allowed? <a class="header-anchor" href="#_7-how-many-submissions-are-allowed" aria-label="Permalink to “7. How many submissions are allowed?”">​</a></h3><p>During the validation phase, each team is allowed to submit up to three times per day per task. In the test phase, each team can submit up to five Docker containers per task in total. The final ranking will be based on the results of the last submission.</p><h3 id="_8-can-we-participate-in-only-one-task" tabindex="-1">8. Can we participate in only one task? <a class="header-anchor" href="#_8-can-we-participate-in-only-one-task" aria-label="Permalink to “8. Can we participate in only one task?”">​</a></h3><p>Yes, participants are free to join any single task. Of course, they are also welcome to participate in multiple or all tasks. Each task will be evaluated, ranked, and awarded independently.</p><h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h1><ol><li><p>All individuals who wish to participate in this challenge are required to register using their real name, affiliation details (including department, university /institute/company name in full, country), and affiliation E-mails. Incomplete and repetitive registrations will be removed without any prior notice. Each team is permitted to have a maximum of six members.</p></li><li><p>During the validation and training phase, all participants must submit a complete solution to this challenge, which includes a Docker image and a qualified methodology paper (of at least 8 pages, in LNCS format).</p></li><li><p>All participants must agree that the short papers they submit can be made publicly available on the challenge website, and that organizers can use information provided by participants, including scores, predicted labels, and papers.</p></li><li><p>Participants are not allowed to register multiple teams or accounts.The MRIxFields Organizers reserve the right to disqualify such participants.</p></li><li><p>Redistribution or transfer of data or data links is prohibited. Participants must use the data solely for their own purposes.</p></li><li><p>Participants should develop fully automated methods based solely on the training set. To ensure the fairness of this challenge, you are only allowed to use the datasets provided by MRIxFields2026. Data augmentation based on the training dataset is allowed. No manual interventions (such as manual annotation of cases) are allowed.</p></li></ol>',22)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
